  /* ======================================================================
     Modernist techniques.
     ----------------------------------------------------------------------
     These are technique templates rather than dishes: the flavour is
     whatever you put in, and what is written down is the mechanism and the
     ratio that makes it work.

     Three things about them that the rest of this file does not have to say.

     Quantities are percentages of the total weight, not fixed grams. A gel
     is "0.5% agar" whatever the batch size, which is why these scale cleanly
     but also why they need a scale that reads to 0.1 g. Eyeballing a
     hydrocolloid does not work.

     They bring allergens of their own. Lecithin is usually soy. Some
     gelatines and clarifying agents are animal-derived. An ingredient that
     arrives as a white powder in a tub still has to go through the same
     review as anything else, and it is easier to forget precisely because it
     does not look like food.

     And several carry real hazards -- an anaerobic bag held warm for hours,
     an enzyme that carries surface bacteria into the middle of a joint, a
     liquid at -196 C. Those are written into the steps where they apply.
     ====================================================================== */

