  /* ======================================================================
     Rubs and marinades.
     ----------------------------------------------------------------------
     Fifty entries under one button: twenty five dry rubs, then twenty five
     wet marinades. All are 'preparation' -- none of them is a dish and none
     of them goes on a menu on its own.

     Written the same way as everything else in this file: from the ratios
     and the mechanism, in our own words, not copied from anywhere. A rub is
     salt plus ground aromatics; a marinade is acid, fat, salt and aromatics.
     Those are facts about cooking rather than anybody's recipe.

     Two things are stated once here and repeated where they matter.

     FIRST, salt. Most rubs below are given with the salt separate, because
     salt is dosed against the WEIGHT OF THE MEAT -- about 1% for a
     seasoning, 1.5% for something held overnight -- while the spice is
     dosed by eye. A rub premixed with salt and then applied by handful
     seasons a thin steak and a whole shoulder identically, which is to say
     one of them wrongly.

     SECOND, safety. Raw meat sits in a marinade, so the marinade is raw
     meat liquid afterwards. It is discarded, or boiled for at least a full
     minute before it is used as a sauce. Marinating happens in the fridge,
     never on the bench. Both are written out again in the marinade section.
     ====================================================================== */

  /* --- Rubs ------------------------------------------------------------------
     Yields are the spice blend only. Anything with sugar in it burns, so the
     entries say where the heat has to come down.
     -------------------------------------------------------------------------- */
