    tags: ['rubs-and-marinades'],
    summary: 'Salt alone, weighed against the meat and left on it. The base every rub sits on.',
    yield: [1, 'ea'],
    ingredients: [
      { qty: 10, unit: 'g', item: 'fine salt', prep: 'per kilogram of meat, for 1%' },
    ],
    steps: [
      { text: 'Weigh the meat and weigh the salt against it. One percent seasons, one and a half percent seasons and firms, and above two percent it is a cure.' },
      { text: 'Apply evenly and refrigerate UNCOVERED on a rack. The salt draws moisture out, that liquid dissolves the salt, and it is drawn back in carrying the seasoning with it.' },
      { text: 'Allow at least four hours for a chicken, overnight for a large joint, forty minutes for a steak. Under about half an hour the surface is wet and will not brown, which is worse than not salting at all.', minutes: 720 },
      { text: 'The uncovered rack is not a detail. A dry surface is what browns, and that is half of what dry brining is for.' },
      { text: 'Do not rinse it off. The salt is in the meat by then, and rinsing only wets the surface again.' },
      { text: 'Every rub below is this method with ground aromatics added. Salt them by weight and the spice by eye.' },
    ],
